const loaded=loadGame();let state=loaded.state;let view=state.location==='village'?'village':'adventure';let keyPage=0,altarKeyId=null;let filter='all';let inventorySort='recent';let logMode='loot';let audioContext;
const $=id=>document.getElementById(id);
const htmlCache=new Map();
function markup(id){return {set html(value){if(htmlCache.get(id)!==value){document.getElementById(id).innerHTML=value;htmlCache.set(id,value);}}};}
const fmt=n=>Math.floor(n).toLocaleString();
