function portrait(){return `<div class="portrait"><canvas id="hero-portrait" width="160" height="150" aria-label="Your ${classInfo().name} hero"></canvas><span id="portrait-level">1</span></div>`;}
function renderHero(){const p=stats(state),archetype=classInfo(),weapon=state.equipment.hand;$('hero-panel').innerHTML=`<div class="hero-card class-${state.heroClass}"><div class="card-eyebrow">YOUR HERO ${icon(archetype.icon)}</div>${portrait()}<h2>${esc(state.name)}</h2><p class="hero-class">${archetype.name.toUpperCase()} <span>·</span> LEVEL <b id="hero-level">${state.level}</b></p><div class="hero-bars"><div class="bar-label"><span>${icon('heart')} Health</span><span id="hp-text"></span></div><div class="meter health-meter"><i id="hero-hp"></i></div><div class="bar-label xp-label"><span>Experience</span><span id="xp-text"></span></div><div class="meter xp-meter"><i id="hero-xp"></i></div></div><div class="stat-grid"><div>${icon(itemIcon(weapon||'hand'))}<strong id="attack-stat">${p.attack}</strong><small>Attack</small></div><div>${icon('shield')}<strong id="defense-stat">${p.defense}</strong><small>Defense</small></div><div>${icon('star')}<strong id="crit-stat">${Math.round(p.crit*100)}%</strong><small>Crit chance</small></div></div><div class="equipment-title"><span>EQUIPPED</span><button class="text-button" data-view="inventory">Manage ${icon('chevron')}</button></div><div class="equipment-row">${Object.entries(state.equipment).map(([slot,item])=>`<button class="equipment-slot grade-${itemGrade(item)} ${!item?'empty':''}" data-action="equipment" data-slot="${slot}" title="${item?esc(item.name):`Empty ${slot} slot`}" aria-label="${item?esc(item.name):`Empty ${slot} slot`}">${icon(itemIcon(item||slot))}<span class="slot-caption">${GEAR[slot].label}</span>${item?`<small>${item.upgrade?`+${item.upgrade}`:''}</small>`:'<small>+</small>'}</button>`).join('')}</div><button class="button character-button" data-view="hero">View character ${icon('arrow')}</button></div><div class="camp-note">${icon('clock')}<div><strong>${weapon?WEAPON_TYPES[weaponType(weapon)].label:'Unarmed'} ${icon(itemIcon(weapon||'hand'))}</strong><p>${archetype.trait}.</p></div></div>`;if($('skills-row'))$('skills-row').innerHTML=skillBar();const c=$('hero-portrait')?.getContext('2d');if(c)drawHero(c,80,131,1.55,0,0,state.heroClass,weaponType(weapon));}
function update(){
 const fieldStats=stats(state);$('field-hp-text').textContent=`${Math.ceil(state.hp)} / ${fieldStats.maxHp}`;$('field-hp-bar').style.width=`${state.hp/fieldStats.maxHp*100}%`;
 const p=stats(state),r=region(state);$('gold').textContent=fmt(state.gold);$('orbs').textContent=fmt(Object.values(state.orbs||{}).reduce((a,b)=>a+b,0));$('bag-count').textContent=state.inventory.length;$('talent-dot').hidden=!state.points;
 $('hero-level').textContent=state.level;$('portrait-level').textContent=state.level;$('hp-text').textContent=`${Math.ceil(state.hp)} / ${p.maxHp}`;$('xp-text').textContent=`${fmt(state.xp)} / ${fmt(xpRequired(state.level))}`;$('hero-hp').style.width=`${state.hp/p.maxHp*100}%`;$('hero-xp').style.width=`${state.xp/xpRequired(state.level)*100}%`;
 $('attack-stat').textContent=p.attack;$('defense-stat').textContent=p.defense;$('crit-stat').textContent=`${Math.round(p.crit*100)}%`;
 $('region-name').textContent=r.name;$('stage-label').innerHTML=`Stage ${state.stage} · Journey ${journey(state)} ${icon('down')}`;$('field-location').textContent=`THE ${r.name.toUpperCase()} ${state.enemy.boss?'SANCTUM':'OUTSKIRTS'}`;$('battlefield').dataset.region=REGIONS.indexOf(r);
 $('enemy-name').textContent=state.enemy.name;$('enemy-level').textContent=`${state.enemy.boss?'BOSS · ':''}Lv. ${state.enemy.level}`;$('enemy-hp').style.width=`${state.enemy.hp/state.enemy.maxHp*100}%`;$('enemy-card').style.opacity=state.enemy.hp>0?'1':'.35';
 $('auto-button').innerHTML=`${icon(state.auto?'pause':'play')} ${state.auto?'Pause battle':'Resume battle'}`;$('speed-button').textContent=`${state.speed}×`;$('auto-advance').checked=state.advance;$('battle-status').textContent=state.auto?(state.respawn>0?'Looking for the next encounter':'Your hero is fighting'):'Resting at camp';markup('live-label').html=state.auto?'<i></i> LIVE BATTLE':'BATTLE PAUSED';$('live-label').classList.toggle('paused',!state.auto);$('battle-overlay').hidden=state.auto;markup('battle-overlay').html=state.auto?'':`<div>${icon('leaf')}<h3>A moment of rest.</h3><p>Ready when you are.</p><button class="button gold-button" data-action="auto">${icon('play')} Resume adventure</button></div>`;
 if(state.location!=='rift')markup('wave-track').html=Array.from({length:5},(_,i)=>`<i class="${i<state.killsInStage?'complete':''} ${state.enemy.boss?'boss-wave':''}">${i===4?icon(state.enemy.boss?'trophy':'star'):''}</i>`).join('');$('wave-count').textContent=state.enemy.boss?'GUARDIAN':`${state.killsInStage} / 5`;
 for(const skill of skillsFor(state)){const lock=state.level<skill.level,cd=state.cooldowns[skill.id]||0,b=document.querySelector(`[data-skill="${skill.id}"]`);if(!b)continue;b.disabled=lock||cd>0||state.respawn>0;b.classList.toggle('locked',lock);$('skill-'+skill.id+'-status').textContent=lock?`Unlocks at level ${skill.level}`:cd>0?`Ready in ${Math.ceil(cd)}s`:'Ready to cast';$('skill-'+skill.id+'-cooldown').innerHTML=lock?icon('lock'):cd>0?Math.ceil(cd)+'s':'';}
 const loot=state.log.filter(x=>logMode==='combat'||x.type==='loot'||x.type==='level'||x.type==='salvage').slice(0,3);markup('loot-feed').html=loot.length?loot.map(x=>`<div class="loot-line"><span class="loot-symbol ${x.type}">${icon(x.type==='loot'?'bag':x.type==='level'?'up':'swords')}</span><div><span>${esc(x.text)}</span><small>${x.type==='loot'?'Added to your inventory':x.type==='level'?'Your legend grows':x.type==='salvage'?'Loot filter · converted to gold':region(state).name+' expedition'}</small></div><time>${new Date(x.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time></div>`).join(''):`<div class="empty-loot">${icon('bag')}<div><strong>Good things lie ahead.</strong><p>Found equipment will appear here as you explore.</p></div></div>`;
 const q=QUESTS.find(q=>!state.claimed.includes(q.id));markup('quest-preview').html=q?`<div class="panel-heading"><h2>${icon('book')} A new chapter</h2><span class="subtle">QUEST</span></div><h3>${q.name}</h3><p>${q.description}</p><div class="quest-progress"><div class="meter"><i style="width:${Math.min(100,q.value(state)/q.target*100)}%"></i></div><span>${Math.min(q.value(state),q.target)} / ${q.target}</span></div><div class="quest-bottom"><span>${icon('coin')} ${q.gold} <span class="subtle">reward</span></span><button class="text-button" ${q.value(state)>=q.target?`data-claim="${q.id}"`:'data-view="journal"'}>${q.value(state)>=q.target?'Claim reward':'View journal'} ${icon('arrow')}</button></div>`:`<div class="panel-heading"><h2>${icon('trophy')} A chapter complete</h2></div><h3>The wild remembers you.</h3><p>All chapter quests completed. The northern realms still await.</p>`;
 updateExpedition(state);
 $('town-teleport').innerHTML=icon('tree')+' '+(state.location==='rift'&&!state.map.completed?'Village · leave rift':'Village');
 $('town-teleport').title=state.location==='rift'?'Leaving ends this single-use rift':'Teleport to town; your expedition progress is kept';
 document.querySelectorAll('[data-action="map"], [data-action="reroll-map"]').forEach(b=>b.disabled=state.location==='rift');
 $('auto-advance').disabled=state.location!=='expedition';
 $('auto-button').disabled=state.location==='village'||(state.location==='rift'&&state.map.completed);
}
function announce(message){const el=$('action-status');el.textContent=message;el.hidden=false;}
function saveLabel(){if(!cloud?.uid)return 'Progress saved locally';
 return {synced:'Synced to your account',syncing:'Syncing to your account…',offline:'Saved on this device · syncs when online',conflict:'Save conflict · open Account',choice:'Choose which progress to keep',unavailable:'Cloud save unavailable · playing locally'}[cloud.status]||'Progress saved locally';}
function persist(syncNow=false){const now=Date.now();let ok;
 if(cloud?.uid&&cloud.record){state.lastSave=now;ok=cloud.save(JSON.stringify(state));}
 else ok=saveGame(state,undefined,now);
 $('save-status').textContent=ok?saveLabel():'Save unavailable in this browser';$('footer-save').innerHTML=ok?`Autosave enabled ${icon('check')}`:'Progress could not be saved';
 if(cloud?.record?.dirty&&(syncNow||now-lastFlush>15000)){lastFlush=now;cloud.flush();}
}
let cloud=null,account=null,accountUser=null,lastFlush=0,conflictShown=false;
function adoptRecord(payload){
 const restored=restorePayload(payload);
 if(restored.recovered){announce('The cloud save could not be read. Your browser save is unchanged.');return;}
 state=restored.state;renderHero();navigate(state.location==='village'?'village':'adventure');update();
 if(restored.offline)setTimeout(()=>showOffline(restored.offline),600);
}
function saveSummary(payload){try{const d=JSON.parse(payload);return `Level ${d.level} · Stage ${d.stage} · ${fmt(d.gold)} gold · ${new Date(d.lastSave||0).toLocaleString([],{dateStyle:'medium',timeStyle:'short'})}`;}catch{return 'Unknown save';}}
function conflictModal(){conflictShown=true;const remote=cloud.remoteConflict;
 modal('Two versions of your legend',`<p class="dialog-description">This device and the cloud both have newer progress. Choose which one continues — the other is overwritten.</p><div class="conflict-grid"><div><strong>This device</strong><p>${esc(saveSummary(cloud.record?.payload))}</p></div><div><strong>Cloud save</strong><p>${esc(remote?saveSummary(remote.payload):'Unavailable')}</p></div></div><div class="item-actions"><button class="button" data-action="resolve-cloud">Keep cloud save</button><button class="button gold-button" data-action="resolve-local">Keep this device</button></div>`);}
function accountModal(){
 if(!account){modal('Account',`<p class="dialog-description">Cloud saves are unavailable right now. Your progress stays safe in this browser.</p>`);return;}
 if(!accountUser){modal('Save your legend to the cloud',`<p class="dialog-description">Sign in with Google to keep your progress across devices. This browser's save stays as a local backup.</p><div class="item-actions"><button class="button gold-button" data-action="sign-in">${icon('user')} Sign in with Google</button></div>`);return;}
 if(cloud?.status==='choice'){modal('Bring this device’s progress?',`<p class="dialog-description">Signed in as <strong>${esc(accountUser.email||'Google account')}</strong>. This account has no cloud save yet.</p><div class="conflict-grid"><div><strong>This device</strong><p>${esc(saveSummary(JSON.stringify(state)))}</p></div><div><strong>Fresh start</strong><p>Begin a new legend on this account.</p></div></div><div class="item-actions"><button class="button" data-action="use-fresh-save">Start fresh</button><button class="button gold-button" data-action="use-device-save">Sync this device</button></div>`);return;}
 if(cloud?.status==='conflict'){conflictModal();return;}
 modal('Your account',`<div class="save-info">${icon('user')}<div><strong>${esc(accountUser.email||'Google account')}</strong><p>${esc(saveLabel())}</p></div></div><div class="item-actions"><button class="button" data-action="sync-now">${icon('check')} Sync now</button><button class="button" data-action="sign-out">Sign out</button></div>`);
}
function updateAccountButton(){const b=$('account-button');if(!b)return;b.title=accountUser?`Signed in as ${accountUser.email||'Google account'}`:'Sign in to sync saves';b.setAttribute('aria-label',b.title);b.classList.toggle('signed-in',!!accountUser);b.classList.toggle('attention',cloud?.status==='conflict'||cloud?.status==='choice');}
function reflectCloud(){$('save-status').textContent=saveLabel();updateAccountButton();if(cloud.status==='conflict'&&!conflictShown)conflictModal();if(cloud.status!=='conflict')conflictShown=false;}
connectAccount().then(fb=>{
 account=fb;
 cloud=new CloudSaves({remote:fb.remote,onChange:reflectCloud});
 fb.onUser(async user=>{
  accountUser=user;
  await cloud.connect(user?user.uid:null);
  updateAccountButton();
  if(!user){persist();return;}
  if(['synced','offline','syncing'].includes(cloud.status)&&cloud.record)adoptRecord(cloud.record.payload);
  else if(cloud.status==='choice')accountModal();
  else if(cloud.status==='unavailable')announce('Cloud saves are unavailable. Playing on this device only.');
  persist();
 });
 updateAccountButton();
}).catch(()=>{/* Firebase unreachable: guest mode continues with local saves. */});
window.addEventListener('online',()=>cloud?.flush());
function sound(freq=440){if(!state.settings.sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();void audioContext.resume();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.035,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.15);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.15);}catch{/* Sound is optional. */}}
function processEvents(events){
 let refreshHero=false,refreshView=false,syncMilestone=false;
 for(const e of events){
  battle.event(e);
  if(e.type==='level'){refreshHero=true;refreshView=true;}
  if(['loot','filteredLoot'].includes(e.type)&&view==='inventory')refreshView=true;
  if(e.type==='keystone'){refreshView=true;syncMilestone=true;}
  if(['complete','stage','newMap','riftWave','riftComplete'].includes(e.type))syncMilestone=true;
  if(e.type==='riftFailed'){navigate('village');syncMilestone=true;}
  if(e.type==='kill'&&['forge','journal','hero'].includes(view))refreshView=true;
  if(e.type==='hit')sound(180);if(e.type==='skill')sound(520);
 }
 if(refreshHero)renderHero();if(refreshView&&view!=='adventure')renderSecondary();if(events.length)update();if(syncMilestone)persist(true);
}
function navigate(next){if(!['adventure','village','hero','inventory','forge','journal'].includes(next))return;
 if(next==='village'&&state.location!=='village'){teleportVillage(state);persist();update();}
 if(next==='adventure'&&state.location==='village')next='village';view=next;$('adventure-view').hidden=view!=='adventure';$('secondary-view').hidden=view==='adventure';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.classList.contains('nav-item'))b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});const titles={village:['Welcome to the Village.','Return to the road, or step beyond the veil.'],adventure:['Into the wild.','A quiet forest. An unwritten legend. Your next step.'],hero:['A legend in the making.','Shape your strength. Find your own way.'],inventory:['Treasures of the wild.','Every discovery has a story. Make it part of yours.'],forge:['Made for the journey.','A little fire. A little patience. A sharper edge.'],journal:['The story so far.','Small victories, waiting to become a saga.']};$('page-title').textContent=titles[view][0];$('page-subtitle').textContent=titles[view][1];$('breadcrumb-view').textContent=view==='hero'?'Character':view[0].toUpperCase()+view.slice(1);if(view!=='adventure')renderSecondary();window.scrollTo({top:0,behavior:'instant'});}
const TALENTS=[['might','swords','Strength of the oak','+3 attack per point'],['guard','shield','An unbroken guard','+2 defense per point'],['vigor','heart','Heart of the wild','+18 maximum health per point'],['fortune','star','A fortunate soul','+1.5% critical chance per point']];
function renderSecondary(){
 const p=stats(state);
 if(view==='village'){if(!state.keystones.some(k=>k.id===altarKeyId))altarKeyId=state.keystones[0]?.id||null;$('secondary-view').innerHTML=villagePanel(state,keyPage,altarKeyId);}
 else if(view==='inventory'){
  $('secondary-view').innerHTML='<div class="possessions-layout">'+equippedPanel(state)+inventoryPanel(state,filter,inventorySort)+'</div>'+essencePouch(state)+keystonePouch(state,keyPage);
  const portrait=$('loadout-portrait');if(portrait)drawHero(portrait.getContext('2d'),120,260,2.8,0,0,state.heroClass,weaponType(state.equipment.hand));
 }else if(view==='forge'){
  $('secondary-view').innerHTML=`<div class="forge-banner"><div class="forge-emblem">${icon('hammer')}</div><div><div class="eyebrow">THE WANDERER’S FORGE</div><h2>Every piece. Made stronger.</h2><p>Each upgrade adds 10% of the original implicit stats. Explicit modifiers stay unchanged.</p></div></div><div class="forge-grid">${Object.entries(state.equipment).map(([slot,item])=>{if(!item)return `<section class="panel forge-card empty-forge">${icon(itemIcon(slot))}<h3>No ${GEAR[slot].label.toLowerCase()} equipped</h3><p>Equip ${GEAR[slot].label.toLowerCase()} gear to start improving it.</p><button class="button" data-view="inventory">Open inventory</button></section>`;const cost=upgradeCost(item),can=state.gold>=cost.gold;return `<section class="panel forge-card grade-${itemGrade(item)}"><span class="item-rarity">${itemLabel(item)} · ${GEAR[slot].label}</span><div class="forge-item-art">${icon(itemIcon(item))}</div><h3>${esc(item.name)}</h3><span class="forge-level">Upgrade +${item.upgrade}</span><div class="upgrade-preview"><span>${primaryPower(item)}<small>${STAT_LABELS[primaryStat(item)]}</small></span>${icon('arrow')}<span class="gold-text">${primaryPower({...item,upgrade:item.upgrade+1})}<small>After upgrade</small></span></div><div class="forge-cost"><span class="${state.gold<cost.gold?'insufficient':''}">${icon('coin')} ${fmt(cost.gold)}</span></div><button class="button gold-button" data-upgrade="${slot}" ${can?'':'disabled'}>${icon('hammer')} ${can?'Upgrade equipment':'Gather more gold'}</button></section>`;}).join('')}</div>${craftingPanel(state)}`;
 }else if(view==='hero'){
  const archetype=classInfo(),activeSkills=skillsFor(state),atTown=state.location==='village';
  $('secondary-view').innerHTML=`<div class="character-layout"><section class="panel character-summary class-${state.heroClass}"><div class="large-portrait"><canvas id="large-portrait" width="240" height="240" aria-label="Your ${archetype.name} hero"></canvas></div><span class="eyebrow">${archetype.name.toUpperCase()} · LEVEL ${state.level}</span><h2>${esc(state.name)}</h2><p>${archetype.description}</p><span class="class-trait">${icon(archetype.icon)} ${archetype.trait}</span><button class="text-button" data-action="rename">Give your hero a name ${icon('feather')}</button><div class="character-stats">${[[itemIcon(state.equipment.hand||'hand'),'Attack',p.attack],['shield','Defense',Number(p.defense.toFixed(1))],['heart','Max health',Number(p.maxHp.toFixed(1))],['star','Critical chance',`${(p.crit*100).toFixed(1)}%`],['trophy','Guardians defeated',state.bosses],['compass','Highest stage',state.maxStage],['sparkles','Fire / Cold / Lightning',p.fire+' / '+p.cold+' / '+p.lightning],['zap','Attack speed bonus',p.haste+'%'],['shield','Elemental resistance',p.resist+'%'],['heart','Life leech',p.leech+'%']].map(([i,label,n])=>`<div>${icon(i)}<span>${label}</span><strong>${n}</strong></div>`).join('')}</div></section><div><section class="panel secondary-panel class-selector"><div class="view-section-title"><div><span class="eyebrow">ARCHETYPE</span><h2>Choose your calling</h2></div><span class="class-location">${atTown?'Village trainer available':'Change in the Village'}</span></div><p class="section-description">Your class changes base combat traits and all three active skills. Any class can wield any weapon; each weapon keeps its own speed, range, and implicit damage.</p><div class="class-card-grid">${Object.entries(HERO_CLASSES).map(([id,c])=>`<button class="class-choice ${state.heroClass===id?'selected':''}" data-class="${id}" ${state.heroClass===id||!atTown?'disabled':''} aria-pressed="${state.heroClass===id}"><span class="class-choice-icon">${icon(c.icon)}</span><strong>${c.name}</strong><small>${c.description}</small><em>${c.trait}</em><b>${state.heroClass===id?'Current class':atTown?'Choose class':'Visit Village'}</b></button>`).join('')}</div></section>${combatPanel(state)}<section class="panel secondary-panel"><div class="view-section-title"><h2>Master your path</h2><span class="points-badge">${state.points} mastery ${state.points===1?'point':'points'}</span></div><p class="section-description">Earn one mastery point with every level. Each choice makes your hero stronger.</p><div class="talents">${TALENTS.map(([id,i,name,desc])=>`<div class="talent-row"><span class="talent-icon">${icon(i)}</span><div><strong>${name}</strong><p>${desc}</p><small>Rank ${state.talents[id]}</small></div><button class="button" data-learn="${id}" aria-label="Improve ${name}" ${state.points>0?'':'disabled'}>+1</button></div>`).join('')}</div></section><section class="panel secondary-panel abilities-panel"><h2>${archetype.name} abilities</h2>${activeSkills.map(s=>`<div class="ability-row"><span class="skill-art ${s.id}">${icon(s.icon)}</span><div><strong>${s.name}</strong><p>${s.description}</p><small>${state.level<s.level?`Unlocks at level ${s.level}`:`${s.cooldown}s cooldown · Press ${s.key} in battle`}</small></div>${state.level<s.level?icon('lock'):icon('check')}</div>`).join('')}</section></div></div>`;
  const c=$('large-portrait').getContext('2d');drawHero(c,120,202,2.4,0,0,state.heroClass,weaponType(state.equipment.hand));
 }else if(view==='journal'){
  $('secondary-view').innerHTML=`<section class="journal-intro"><span class="chapter-number">I</span><div><div class="eyebrow">CHAPTER ONE</div><h2>Whispers in the Mistwood</h2><p>Beyond the last lantern of home, the forest is stirring. Sharpen your blade, follow the old paths, and discover what guards the way north.</p></div></section><div class="journal-quests">${QUESTS.map(q=>{const done=state.claimed.includes(q.id),ready=q.value(state)>=q.target;return `<section class="panel journal-quest ${done?'quest-complete':''}"><span class="quest-icon">${icon(done?'check':q.id==='forge'?'hammer':q.id==='guardian'?'trophy':'compass')}</span><div class="quest-details"><h3>${q.name}</h3><p>${q.description}</p><div class="quest-progress"><div class="meter"><i style="width:${Math.min(100,q.value(state)/q.target*100)}%"></i></div><span>${Math.min(q.value(state),q.target)} / ${q.target}</span></div></div><div class="quest-rewards"><span>${icon('coin')} ${q.gold}</span><button class="button ${ready&&!done?'gold-button':''}" data-claim="${q.id}" ${done||!ready?'disabled':''}>${done?`${icon('check')} Collected`:ready?'Claim rewards':'In progress'}</button></div></section>`}).join('')}</div><section class="panel secondary-panel journey-stats"><h2>Footprints along the way</h2><div>${[['Creatures defeated',state.kills],['Guardians overcome',state.bosses],['Equipment forged',state.crafted],['Highest stage',state.maxStage]].map(([label,n])=>`<span><strong>${fmt(n)}</strong><small>${label}</small></span>`).join('')}</div></section>`;
 }
}
function modal(title,body,cls=''){const d=$('dialog');$('dialog-content').innerHTML=`<div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body ${cls}">${body}</div>`;if(!d.open)d.showModal();}
function showMap(cycle=journey(state)-1){modal('The Northern Realms',worldMapPanel(state,cycle),'map-dialog');}
function inspectItem(id,equipped=false){const item=equipped?Object.values(state.equipment).find(i=>i?.id===id):state.inventory.find(i=>i.id===id);if(!item)return;const current=state.equipment[item.slot],power=primaryPower(item),delta=Number((power-(current?primaryPower(current):0)).toFixed(1)),profile=item.slot==='hand'?WEAPON_TYPES[weaponType(item)]:null;modal('A closer look',`<div class="item-detail grade-${itemGrade(item)}"><span class="item-rarity">${itemLabel(item)} · ${profile?.label||GEAR[item.slot].label}</span><div class="detail-art">${icon(itemIcon(item))}</div><h3>${esc(item.name)}${item.upgrade?' +'+item.upgrade:''}</h3><p>${profile?`${profile.description} · ${profile.attackRange} tile range · ${(1/profile.attackInterval).toFixed(2)} attacks/sec`:`${GEAR[item.slot].label} gear`} · item level ${item.itemLevel}</p><div class="detail-stat"><span>${STAT_LABELS[primaryStat(item)]}</span><strong>${power}</strong>${!equipped?`<span class="${delta>=0?'positive':'negative'}">${delta>=0?'+':''}${delta} vs. equipped</span>`:''}</div>${implicitMarkup(item)}${!equipped&&RING_SLOTS.includes(item.slot)?RING_SLOTS.map(slot=>`<h4>Compare with ${GEAR[slot].label.toLowerCase()}</h4>${itemAffixDetails({...item,slot},state)}`).join(''):itemAffixDetails(item,state)}<div class="item-actions"><button class="button" data-lock-item="${esc(id)}" aria-pressed="${!!item.locked}">${icon('lock')} ${item.locked?'Unlock item':'Lock item'}</button>${equipped?`<button class="button gold-button" data-action="go-forge">${icon('hammer')} Improve at the forge</button>`:`${equipButtons(item)}<button class="button" data-salvage="${id}" ${item.locked?'disabled title="Unlock this item to salvage it"':''}>${item.locked?'Locked · ':''}Salvage · ${salvageGold(item)} ${icon('coin')}</button>`}</div></div>`);}
function settings(){modal('Make yourself at home',`<div class="settings-row"><div><strong>Battle sounds</strong><p>Soft audio for attacks and abilities.</p></div><label class="switch-label"><input type="checkbox" id="setting-sound" aria-label="Battle sounds" ${state.settings.sound?'checked':''}><span class="switch"></span></label></div><div class="settings-row"><div><strong>Ambient motion</strong><p>Animated heroes and drifting fireflies.</p></div><label class="switch-label"><input type="checkbox" id="setting-motion" aria-label="Ambient motion" ${state.settings.motion?'checked':''}><span class="switch"></span></label></div><div class="save-info">${icon('shield')}<div><strong>Your saga stays with you.</strong><p>Progress saves automatically in this browser. Use the same browser and device to continue. Offline rewards run at 50% battle efficiency, for up to 8 hours, when battle is active.</p></div></div><button class="button" data-action="help">${icon('info')} How to play</button>`);}
function help(){modal('Welcome to the wild',`<p class="dialog-description">Walk the northern paths as a durable Vanguard, swift Ranger, or elemental Mage. Change your calling with the trainer in the Village; your level, mastery, equipment, and progress stay with you.</p><p class="dialog-description">Visit the Village at any time. Its return portal preserves your expedition; its entrance starts a fresh stage. Keystones drop only from defeated monsters. At the keystone altar, apply orbs to a found keystone to change its rarity, modifiers, or rolls. Each keystone opens a rift with four monster waves and a final boss. Enter once: death or teleporting out ends that rift. Difficulty modifiers improve item level, quantity, and rarity.</p><div class="help-steps">${[['swords','Adventure at your own pace','Battles run automatically. Tap the clearing to move, or pause whenever you like. Progression is endless: each set of 20 stages revisits the four regions with stronger enemies and higher-level loot. Every stage has a generated map with one winding route to the boss. Defeat normal, magic, and rare enemies to fill the guardian bar, then defeat the unique stage boss. Auto advance enters the next stage; switch it off to farm fresh maps of the current stage.'],['zap','Command your class abilities','Each class has a damage skill, a recovery skill at level 3, and a powerful area skill at level 5. Watch boss telegraphs and use your class range to stay clear. On desktop, use keys 1, 2, and 3. Space pauses battle.'],['bag','Make every discovery count','Equip armor, jewelry, and a weapon: one-hand sword, two-hand greatsword, bow, or staff. Weapons have distinct damage, attack speed, range, critical, and elemental profiles; any class can wield any weapon. Rings fit either finger. Inspect a bag slot to equip or instantly salvage it. Lock favorites to protect them. Equipment modifiers include movement speed, attack speed, reach, critical strike chance and multiplier, elemental damage, life leech, and resistance. Loot appears on the battlefield before collection. Customize the Loot filter, salvage spare gear for gold and essences, and craft at the forge. Item grade is the strongest explicit modifier: D, C, B, A, AA, AAA, AAAA, AAAAA, S.'],['user','Find your path','Spend a mastery point every time you level up. Claim quest rewards in your journal. If a guardian is too strong, return to an earlier stage from the world map.'],['clock','Return to a little progress','With battle active, earn gold, experience, and orbs while away. Offline rewards use half your battle rate, capped at 8 hours; they do not advance stages.']].map(([i,t,p])=>`<div>${icon(i)}<section><h3>${t}</h3><p>${p}</p></section></div>`).join('')}</div><button class="button gold-button" data-action="close">Your adventure awaits ${icon('arrow')}</button>`);}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.action==='resume-expedition'){if(resumeExpedition(state)){navigate('adventure');update();persist();}}
 if(b.dataset.action==='enter-rift'){if(enterRift(state)){navigate('adventure');update();persist();announce('Rift entered. The portal has been consumed.');}}
 if(b.dataset.action==='inspect-rift-portal'&&state.riftPortal)modal('Your open rift',keystoneDetails(state.riftPortal));
 if(b.dataset.action==='rift-info'&&state.rift)modal('Rift difficulty & rewards',keystoneDetails(state.rift.keystone));
 if(b.dataset.keyPage!==undefined){keyPage=Number(b.dataset.keyPage);renderSecondary();}
 if(b.dataset.keystone){const key=state.keystones.find(k=>k.id===b.dataset.keystone);if(key)modal('Inspect keystone',keystoneDetails(key)+(state.location==='village'?'<button class="button gold-button" data-open-rift="'+key.id+'" '+(state.riftPortal?'disabled':'')+'>Open portal · consume keystone</button>'+(state.riftPortal?'<p class="small-description">You already have an open rift portal.</p>':''):'<button class="button" data-action="key-town">Teleport to Village</button>'));}
 if(b.dataset.action==='key-town'){$('dialog').close();navigate('village');}
 if(b.dataset.openRift){if(openRiftPortal(state,b.dataset.openRift)){$('dialog').close();renderSecondary();update();persist();announce('Rift portal opened. One entry remains.');}}
 if(b.dataset.altarKey){altarKeyId=b.dataset.altarKey;renderSecondary();return;}
 if(b.dataset.craftKeystone!==undefined){const result=craftKeystone(state,b.dataset.keyId,b.dataset.craftKeystone,Math.random);if(result.ok){altarKeyId=result.item.id;renderSecondary();update();persist();announce(result.operation+' shaped the keystone.','loot');}else announce(result.reason);}
 if(b.dataset.filter){filter=b.dataset.filter;renderSecondary();}
 if(b.dataset.item)inspectItem(b.dataset.item,b.dataset.equipped==='true');
 if(b.dataset.action==='equipment'){const item=state.equipment[b.dataset.slot];if(item)inspectItem(item.id,true);else{filter=RING_SLOTS.includes(b.dataset.slot)?'rings':b.dataset.slot;navigate('inventory');}}
 if(b.dataset.action==='map')showMap();
 if(b.dataset.mapCycle!==undefined)showMap(Number(b.dataset.mapCycle));
 if(b.dataset.action==='loot-filter')modal('Your loot filter',lootFilterPanel(state));
 if(b.dataset.lootPreset)modal('Your loot filter',lootFilterPanel(state,normalizeLootFilter({minGrade:b.dataset.lootPreset==='high'?2:0,minEssenceGrade:state.lootFilter.minEssenceGrade})));
 if(b.dataset.action==='collect-ground'){const events=[];for(const drop of [...state.groundLoot])collectLoot(state,drop.id,events);processEvents(events);persist();}
 if(b.dataset.action==='enemy-info')modal('Enemy dossier',enemyDetails(state));
 if(b.dataset.action==='threat-guide')modal('Enemies of the northern realms',threatGuide());
 if(b.dataset.action==='expedition-map'){modal('Your expedition',expeditionOverview(state));updateExpedition(state);}
 if(b.dataset.action==='reroll-map')modal('Explore a new path',`<p class="dialog-description">Generate a fresh map of stage ${state.stage}. Your current map’s guardian progress will reset. Your hero, equipment, gold, and unlocked stages are kept.</p><div class="reroll-actions"><button class="button" data-action="close">Keep exploring</button><button class="button gold-button" data-action="confirm-reroll">${icon('compass')} Generate new map</button></div>`);
 if(b.dataset.action==='confirm-reroll'&&state.location==='expedition'){startExpedition(state);$('dialog').close();update();persist();announce('A new path through '+region(state).name+'.');}
 if(b.dataset.craft||b.dataset.applyEssence){
  const item=craftTarget(state,$('craft-item')?.value);
  const result=b.dataset.craft?craft(state,item,b.dataset.craft):applyEssence(state,item,b.dataset.applyEssence);
  if(result.ok){if(result.success!==false)sound(560);announce(b.dataset.craft?CRAFT_OPERATIONS[b.dataset.craft].name+' applied · '+itemLabel(item):result.reason);renderHero();}else announce(result.reason);
  if(view==='forge')renderSecondary();update();persist();
 }
 if(b.dataset.action==='mod-dictionary')modal('Modifier dictionary',modDictionary(state));
 if(b.dataset.essence){selectEssence(b.dataset.essence);renderSecondary();document.querySelector(`[data-essence="${CSS.escape(b.dataset.essence)}"]`)?.focus();}
 if(b.dataset.essenceGrade){selectEssenceFilter('grade',b.dataset.essenceGrade);renderSecondary();document.querySelector(`[data-essence-grade="${CSS.escape(b.dataset.essenceGrade)}"]`)?.focus();}
 if(b.dataset.essenceKind){selectEssenceFilter('kind',b.dataset.essenceKind);renderSecondary();document.querySelector(`[data-essence-kind="${CSS.escape(b.dataset.essenceKind)}"]`)?.focus();}
 if(b.dataset.discardEssenceOne){
  const n=discardEssence(state,b.dataset.discardEssenceOne,1);
  if(n){renderSecondary();update();persist();announce('Discarded one essence.');}
 }
 if(b.dataset.discardEssence){
  const essence=state.essences?.find(x=>x.id===b.dataset.discardEssence);
  if(essence)modal('Discard essences',`<p class="dialog-description">Discard <strong>${esc(b.dataset.essenceLabel||'this modifier')}</strong>? <b>${fmt(essence.count)}</b> ${essence.count===1?'copy':'copies'} would be lost forever.</p><div class="reroll-actions"><button class="button" data-action="close">Keep it</button><button class="button gold-button" data-confirm-discard-essence="${esc(essence.id)}">Discard ${fmt(essence.count)} ${icon('close')}</button></div>`);
 }
 if(b.dataset.confirmDiscardEssence){
  const n=discardEssence(state,b.dataset.confirmDiscardEssence);
  if(n){$('dialog').close();renderSecondary();update();persist();announce('Discarded '+n+' essence'+(n===1?'':'s')+'.');}
 }
 if(b.dataset.action==='close')$('dialog').close();
 if(b.dataset.action==='account')accountModal();
 if(b.dataset.action==='sign-in')account?.signIn().catch(()=>announce('Sign-in did not complete. Try again.'));
 if(b.dataset.action==='sign-out'){persist(true);$('dialog').close();(cloud?.flush()||Promise.resolve()).finally(()=>account?.signOut());}
 if(b.dataset.action==='sync-now'){cloud?.flush();$('dialog').close();announce('Syncing to your account…');}
 if(b.dataset.action==='use-device-save'){if(cloud?.start(JSON.stringify(state))){cloud.flush();$('dialog').close();announce('This device’s progress now syncs to your account.','success');}}
 if(b.dataset.action==='use-fresh-save'){const fresh=createGame();if(cloud?.start(JSON.stringify(fresh))){state=fresh;$('dialog').close();cloud.flush();renderHero();navigate('adventure');update();announce('A new legend begins on your account.','success');}}
 if(b.dataset.action==='resolve-local')cloud?.resolve('local').then(ok=>{if(ok){$('dialog').close();announce('This device’s progress now syncs to your account.','success');}else if(cloud.status==='conflict')conflictModal();});
 if(b.dataset.action==='resolve-cloud')cloud?.resolve('cloud').then(ok=>{if(ok){$('dialog').close();adoptRecord(cloud.record.payload);announce('Cloud progress restored to this device.','success');}else if(cloud.status==='conflict')conflictModal();});
 if(b.dataset.action==='settings')settings();
 if(b.dataset.action==='help')help();
 if(b.dataset.action==='go-forge'){$('dialog').close();navigate('forge');}
 if(b.dataset.action==='rename')modal('A name for your legend',`<form id="rename-form"><label class="name-label" for="hero-name">Hero name</label><input id="hero-name" name="heroName" value="${esc(state.name)}" maxlength="20" minlength="1" required autocomplete="off"><p class="small-description">Up to 20 characters.</p><button class="button gold-button" type="submit">Save name ${icon('check')}</button></form>`);
 if(b.dataset.class){if(chooseClass(state,b.dataset.class)){renderHero();renderSecondary();update();persist();announce('You are now a '+classInfo().name+'. Your active skills have changed.','success');}return;}
 let changed=false;
 if(b.dataset.equip){changed=equip(state,b.dataset.equip,b.dataset.equipSlot);if(changed){$('dialog').close();announce('Equipment ready for the road.','success');}}
 if(b.dataset.lockItem){
  const item=state.inventory.find(i=>i.id===b.dataset.lockItem)||Object.values(state.equipment).find(i=>i?.id===b.dataset.lockItem);
  if(item){changed=setItemLocked(state,item.id,!item.locked);if($('dialog').open)inspectItem(item.id,!state.inventory.includes(item));}
 }
 if(b.dataset.action==='salvage-junk'){
  const gold=state.gold,essences=essenceCount(state);let count=0;
  for(const item of salvageCandidates(state,filter))if(salvage(state,item.id))count++;
  changed=count>0;if(changed)announce('Salvaged '+count+' items for '+(state.gold-gold)+' gold and '+(essenceCount(state)-essences)+' essences.');
 }
 if(b.dataset.salvage){
  const item=state.inventory.find(i=>i.id===b.dataset.salvage);
  if(item){const gold=salvageGold(item),before=essenceCount(state);changed=salvage(state,item.id);if(changed){$('dialog').close();announce('Salvaged for '+gold+' gold and '+(essenceCount(state)-before)+' essences.');}}
 }
 if(b.dataset.upgrade){changed=upgrade(state,b.dataset.upgrade);if(changed){announce(`${state.equipment[b.dataset.upgrade].name} upgraded to +${state.equipment[b.dataset.upgrade].upgrade}.`,'success');sound(620);}}
 if(b.dataset.learn){changed=learn(state,b.dataset.learn);if(changed)announce('Mastery improved. Your hero grows stronger.','success');}
 if(b.dataset.travel){changed=travel(state,Number(b.dataset.travel));if(changed){$('dialog').close();navigate('adventure');announce(`Arrived at ${region(state).name}, stage ${state.stage}.`);}}
 if(changed){renderHero();if(view!=='adventure')renderSecondary();update();persist();}
 if(b.dataset.claim&&view==='journal')renderSecondary();
});
document.addEventListener('change',e=>{if(e.target.id==='inventory-filter'){filter=e.target.value;renderSecondary();$('inventory-filter').focus();}if(e.target.id==='inventory-sort'){inventorySort=e.target.value;renderSecondary();$('inventory-sort').focus();}if(e.target.id==='setting-motion'){state.settings.motion=e.target.checked;persist();}if(e.target.id==='setting-sound'){state.settings.sound=e.target.checked;$('sound-button').innerHTML=icon(state.settings.sound?'sound':'mute');$('sound-button').setAttribute('aria-label',state.settings.sound?'Mute sound':'Enable sound');sound();persist();}if(e.target.id==='craft-item'){selectCraftItem(e.target.value);renderSecondary();}});
document.addEventListener('submit',e=>{
 if(e.target.id==='loot-filter-form'){e.preventDefault();state.lootFilter=filterFromForm(e.target);$('dialog').close();update();persist();announce('Loot filter saved.');}
 if(e.target.id==='village-stage-form'){e.preventDefault();if(startVillageStage(state,Number(new FormData(e.target).get('stage')))){navigate('adventure');update();persist();}}
 if(e.target.id==='stage-travel-form'){e.preventDefault();const stage=Number(new FormData(e.target).get('stage'));if(travel(state,stage)){$('dialog').close();navigate('adventure');update();persist();}}
});
document.addEventListener('input',e=>{if(e.target.closest('#loot-filter-form'))updateFilterPreview(state,e.target.closest('form'));if(e.target.id==='essence-search'){const query=e.target.value.trim().toLowerCase();document.querySelectorAll('[data-essence-search]').forEach(card=>card.hidden=query&&!card.dataset.essenceSearch.includes(query));const visible=[...document.querySelectorAll('[data-essence-search]')].filter(card=>!card.hidden).length;document.querySelector('.essence-search-results')?.remove();if(!visible){const note=document.createElement('p');note.className='essence-search-results';note.textContent='No visible essences match that search.';document.querySelector('.essence-card-grid')?.append(note);}}});
document.addEventListener('submit',e=>{if(e.target.id!=='rename-form')return;e.preventDefault();const name=$('hero-name').value.trim();if(!name){$('hero-name').setCustomValidity('Please enter a name.');$('hero-name').reportValidity();return;}state.name=name.slice(0,20);$('dialog').close();renderHero();renderSecondary();update();persist();announce('A new name. The same brave heart.','success');});
document.addEventListener('input',e=>{if(e.target.id==='hero-name')e.target.setCustomValidity('');});
$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('dialog').close();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.skill)processEvents(useSkill(state,b.dataset.skill));if(b.dataset.log){logMode=b.dataset.log;document.querySelectorAll('[data-log]').forEach(x=>x.classList.toggle('active',x===b));update();}if(b.dataset.action==='auto'&&state.location!=='village'){state.auto=!state.auto;update();persist();}if(b.dataset.action==='speed'){state.speed=state.speed===1?2:1;update();}if(b.dataset.action==='sound'){state.settings.sound=!state.settings.sound;b.innerHTML=icon(state.settings.sound?'sound':'mute');b.setAttribute('aria-label',state.settings.sound?'Mute sound':'Enable sound');sound();persist();}if(b.dataset.claim){if(claimQuest(state,b.dataset.claim)){announce('Quest rewards collected.','success');update();if(view==='journal')renderSecondary();persist();}}});
document.addEventListener('change',e=>{if(e.target.id==='auto-advance'){state.advance=e.target.checked;persist();}});
document.addEventListener('keydown',e=>{if(e.repeat||$('dialog').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const skill=skillsFor(state).find(s=>s.key===e.key);if(skill){e.preventDefault();processEvents(useSkill(state,skill.id));}if(e.code==='Space'&&state.location!=='village'&&!e.target.closest('button,a')){e.preventDefault();state.auto=!state.auto;update();}});
mount();const battle=new Battlefield($('battle-canvas'),()=>state,(x,y,targetId)=>{if(!movePlayer(state,x,y,targetId))announce('Choose open ground or a revealed enemy.');update();},dropId=>{const events=[];if(collectLoot(state,dropId,events)){processEvents(events);persist();}});
if(state.location==='village')navigate('village');
let previous=performance.now(),uiElapsed=0;setInterval(()=>{const now=performance.now(),dt=Math.min(.5,(now-previous)/1000);previous=now;if(document.hidden)return;processEvents(tick(state,dt));uiElapsed+=dt;if(uiElapsed>.25){update();uiElapsed=0;}},100);
setInterval(()=>{if(!document.hidden)persist();},5000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)persist(true);else{const rewards=offlineRewards(state);if(rewards)showOffline(rewards);previous=performance.now();update();}});
window.addEventListener('pagehide',()=>persist(true));
function showOffline(r){addLog(state,'While away: '+fmt(r.gold)+' gold, '+fmt(r.xp)+' experience and '+(r.orbs||[]).length+' orbs.','loot');renderHero();update();persist();}
if(loaded.migrated)announce('Your hero is ready for the new expeditions. Equipment and progress preserved.','success');
if(loaded.offline)setTimeout(()=>showOffline(loaded.offline),600);if(loaded.recovered)announce('The previous save could not be read. A new journey has begun.');
// Progressive enhancement for browsers implementing the page-scoped WebMCP registry.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'read_adventure',description:'Read the current hero, resources, stage, and battle status.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({name:state.name,heroClass:state.heroClass,weaponType:weaponType(state.equipment.hand),level:state.level,stage:state.stage,maxStage:state.maxStage,gold:state.gold,orbs:Object.fromEntries(Object.entries(state.orbs||{}).filter(([,n])=>n>0)),location:state.location,keystones:state.keystones.length,riftWave:state.rift?.wave||null,battleActive:state.auto&&state.location!=='village',stats:stats(state),expedition:{seed:state.map.seed,name:state.map.name,progress:state.map.progress,goal:state.map.goal,bossUnlocked:state.map.bossUnlocked},enemy:{name:state.enemy.name,tier:state.enemy.tier,modifiers:state.enemy.modifiers}})});
 register({name:'set_battle_active',description:'Resume or pause automatic battle using the same control as the visible interface.',inputSchema:{type:'object',properties:{active:{type:'boolean'}},required:['active'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.active!=='boolean'||Object.keys(input).some(k=>k!=='active'))throw Error('active must be a boolean');if(state.location==='village'&&input.active)throw Error('Use the expedition entrance or a portal to leave the Village first');state.auto=input.active;update();persist();return {battleActive:state.auto};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
